targets.expr:
(
sum by (expert, repo) (increase(lazycortex_runtime_expert_jobs_total{repo=~"$repo",outcome="done"}[$period])) or 0 * sum by (expert, repo) (increase(lazycortex_runtime_expert_jobs_total{repo=~"$repo"}[$period]))
) / clamp_min(sum by (expert, repo) (increase(lazycortex_runtime_expert_jobs_total{repo=~"$repo"}[$period])), 1)

(
sum by (expert, repo) (increase(lazycortex_runtime_expert_job_duration_seconds_sum{repo=~"$repo"}[$period])) or 0 * sum by (expert, repo) (increase(lazycortex_runtime_expert_jobs_total{repo=~"$repo"}[$period]))
) / 3600
